const cnpj = String($json.cnpj || '').replace(/[^0-9A-Za-z]/g, '').toUpperCase();

if (cnpj.length !== 14) {
  throw new Error('CNPJ inválido: precisa ter 14 caracteres');
}

return [{ json: { cnpj } }];

const input = $input.first().json;

const sucesso = !input.error && !!input.cnpj;

const dados = sucesso ? {
  razao_social: input.razao_social || '',
  nome_fantasia: input.nome_fantasia || input.razao_social || '',
  endereco: [
    input.logradouro,
    input.numero,
    input.bairro,
    input.municipio,
    input.uf
  ].filter(Boolean).join(', '),
  cnae: input.cnae_fiscal_descricao || ''
} : null;

return [{
  json: {
    sucesso,
    dados,
    erro: sucesso ? null : 'CNPJ não encontrado ou serviço indisponível no momento'
  }
}];
